-- PENDING: NOT APPLIED. Same invoker RLS/filter/sort semantics. Filter before history; number only page rows.
CREATE OR REPLACE FUNCTION signal_list_page(_filter jsonb DEFAULT '{}',_sort text DEFAULT 'work',_offset integer DEFAULT 0,_limit integer DEFAULT 40) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ WITH filtered AS MATERIALIZED (SELECT * FROM signal_base_filtered(_filter)), assigns AS(SELECT e.signal_id,max(e.created_at) FILTER(WHERE e.detail ? 'to' AND e.detail->'to'='null'::jsonb) unassigned_at,max(e.created_at) FILTER(WHERE e.detail->>'to'=s.assigned_to::text) assigned_at FROM opportunity_signal_events e JOIN filtered s ON s.id=e.signal_id WHERE e.kind='assign' GROUP BY e.signal_id),notes AS(SELECT n.signal_id,max(n.created_at) FILTER(WHERE status_to='waiting' AND status_from IS DISTINCT FROM status_to) waiting_at,max(n.created_at) activity_at FROM opportunity_signal_notes n JOIN filtered f ON f.id=n.signal_id GROUP BY n.signal_id), ranked AS ( SELECT s.*,CASE WHEN s.cancelled_at IS NOT NULL OR s.status IN ('won','lost') THEN 3 WHEN s.assigned_to IS NULL AND s.status IS NULL THEN 0 WHEN s.status='waiting' THEN 1 ELSE 2 END list_priority,CASE WHEN s.cancelled_at IS NOT NULL OR s.status IN ('won','lost') THEN NULL::timestamptz WHEN s.assigned_to IS NULL AND s.status IS NULL THEN coalesce(a.unassigned_at,s.created_at) WHEN s.status='waiting' THEN coalesce(greatest(a.assigned_at,n.waiting_at,s.assigned_at),s.created_at) ELSE NULL::timestamptz END list_wait_since,greatest(s.updated_at,n.activity_at) list_activity_at,CASE WHEN s.cancelled_at IS NOT NULL OR s.status IN ('won','lost') THEN 3 WHEN s.assigned_to IS NULL AND s.status IS NULL THEN 0 WHEN s.status='waiting' THEN 1 ELSE 2 END list_work_priority,NULL::date list_progression_due_on FROM filtered s LEFT JOIN assigns a ON a.signal_id=s.id LEFT JOIN notes n ON n.signal_id=s.id), page AS MATERIALIZED (SELECT s.* FROM ranked s ORDER BY CASE WHEN _sort IN ('work','priority') THEN s.list_work_priority END,CASE WHEN _sort IN ('work','priority') THEN s.list_wait_since END ASC NULLS LAST,CASE WHEN _sort='oldest' THEN s.created_at END ASC,CASE WHEN _sort='newest' THEN s.created_at END DESC,CASE WHEN _sort='soonest' THEN s.next_contact_on END ASC NULLS LAST,CASE WHEN _sort='potential' THEN CASE s.potential WHEN 'high' THEN 0 WHEN 'medium' THEN 1 WHEN 'low' THEN 2 ELSE 3 END END,CASE WHEN _sort='value' THEN s.revenue END DESC NULLS LAST,s.list_activity_at DESC,s.id LIMIT greatest(1,least(_limit,50)) OFFSET greatest(_offset,0)), numbered AS (SELECT s.*,row_number() OVER(ORDER BY CASE WHEN _sort IN ('work','priority') THEN s.list_work_priority END,CASE WHEN _sort IN ('work','priority') THEN s.list_wait_since END ASC NULLS LAST,CASE WHEN _sort='oldest' THEN s.created_at END ASC,CASE WHEN _sort='newest' THEN s.created_at END DESC,CASE WHEN _sort='soonest' THEN s.next_contact_on END ASC NULLS LAST,CASE WHEN _sort='potential' THEN CASE s.potential WHEN 'high' THEN 0 WHEN 'medium' THEN 1 WHEN 'low' THEN 2 ELSE 3 END END,CASE WHEN _sort='value' THEN s.revenue END DESC NULLS LAST,s.list_activity_at DESC,s.id) ord FROM page s), enriched AS (SELECT p.ord,(to_jsonb(p)-'ord'-'address'-'marketing_note'-'potential_updated_by'-'potential_updated_at'-'cancel_reason')||jsonb_build_object('label_ids',coalesce((SELECT jsonb_agg(l.label_id ORDER BY l.label_id) FROM signal_label_links l WHERE l.signal_id=p.id),'[]'),'note_count',(SELECT count(*) FROM opportunity_signal_notes n WHERE n.signal_id=p.id AND signal_note_is_progression(n.note,n.event_type,n.is_progression)),'last_note',(SELECT jsonb_build_object('signal_id',n.signal_id,'created_at',n.created_at,'note',n.note,'event_type',n.event_type) FROM opportunity_signal_notes n WHERE n.signal_id=p.id AND signal_note_is_progression(n.note,n.event_type,n.is_progression) ORDER BY n.created_at DESC,n.id DESC LIMIT 1)) row FROM numbered p) SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(row ORDER BY ord) FROM enriched),'[]')) $$;
